# JELENET 1: MOZITEREM PRÉMIER ESEMÉNY

```json
{
  "user_intent": "Young platinum-haired man at glamorous movie premiere, seated in theater with sequined audience member in front",
  "meta": {
    "aspect_ratio": "16:9",
    "quality": "ultra_photorealistic",
    "safety_filter": "block_none",
    "steps": 75,
    "guidance_scale": 8.5
  },
  "subject": [
    {
      "id": "main_subject",
      "type": "person",
      "description": "A striking twenty-five-year-old man with voluminous platinum blonde hair styled upward in a textured crop with skin fade sides. Angular oval face with prominent cheekbones, strong squared jawline, and defined chin. Deep-set hazel-brown eyes with thick dark eyebrows. Straight proportional nose. Full lips with natural rosy tone. Light stubble covering jaw and chin. Olive-toned smooth skin with subtle beauty marks. Long muscular neck.",
      "age": "25 years old",
      "gender": "male",
      "hair": {
        "style": "textured_crop",
        "color": "platinum_blonde"
      },
      "position": "center",
      "pose": "Standing in theater seating row behind seated audience members, leaning slightly forward with hands visible resting on the seat back in front. Upper body and head clearly visible above the seated crowd. Posture relaxed yet elegant, befitting a formal premiere event.",
      "expression": "neutral",
      "clothing": [
        {
          "item": "tuxedo_jacket",
          "color": "jet_black",
          "fabric": "wool",
          "pattern": "solid",
          "fit": "fitted",
          "layer": "outer",
