        },
        {
          "item": "bow_tie",
          "color": "black",
          "fabric": "silk",
          "pattern": "solid",
          "fit": "fitted",
          "layer": "outer",
          "details": "Hand-tied black silk bow tie, perfectly symmetrical."
        }
      ],
      "accessories": []
    },
    {
      "id": "foreground_audience",
      "type": "person",
      "description": "Middle-aged woman with short dark hair seated directly in front of main subject, wearing elaborate silver sequined jacket that catches light dramatically. She is laughing heartily with head tilted back, mouth wide open in genuine amusement.",
      "position": "foreground",
      "pose": "Seated, leaning back slightly while laughing",
      "expression": "laughing"
    },
    {
