    "time": "evening",
    "weather": "N/A - Indoor",
    "lighting": {
      "type": "cinematic",
      "direction": "front_lit",
      "detailed_description": "Theatrical lighting combining dim ambient theater illumination with reflected light from the projection screen illuminating faces. The lighting creates a warm, intimate atmosphere typical of premiere screenings. Sequins on foreground subject catch and reflect light in multiple directions creating sparkle effects. Soft fill light prevents faces from falling into complete shadow while maintaining cinema ambiance."
    },
    "background_elements": [
      "Multiple rows of theater seating receding into background",
      "Diverse audience members in formal attire - suits, gowns, cocktail dresses",
      "Soft ambient theater lighting from ceiling fixtures",
      "Dark theater walls creating intimate enclosed space"
    ]
  },
  "technical": {
    "camera_model": "Canon EOS R5",
    "lens": "50mm",
    "aperture": "f/2.8",
